window.suitePagination=(total,page,pageSize,itemLabel='records')=>{const pageCount=Math.max(1,Math.ceil(total/pageSize)),first=total?((page-1)*pageSize)+1:0,last=Math.min(page*pageSize,total),start=Math.max(1,Math.min(page-2,pageCount-4)),pages=Array.from({length:Math.min(5,pageCount)},(_,index)=>start+index);return `<nav class="suite-pagination" aria-label="Table pages"><div class="suite-pagination-summary">Showing <strong>${first}–${last}</strong> of <strong>${total}</strong> ${itemLabel}</div><div class="suite-pagination-controls"><label class="suite-page-size"><span>Rows per page</span><select data-suite-page-size aria-label="Rows per page">${[5,10,25,50].map(size=>`<option value="${size}" ${pageSize===size?'selected':''}>${size}</option>`).join('')}</select></label><div class="suite-page-buttons"><button type="button" data-suite-page="${Math.max(1,page-1)}" aria-label="Previous page" ${page<=1?'disabled':''}>‹</button>${pages.map(number=>`<button type="button" data-suite-page="${number}" aria-label="Page ${number}" aria-current="${number===page?'page':'false'}" class="${number===page?'active':''}">${number}</button>`).join('')}<button type="button" data-suite-page="${Math.min(pageCount,page+1)}" aria-label="Next page" ${page>=pageCount?'disabled':''}>›</button></div></div></nav>`;};
